split_clients "${remote_addr}${http_user_agent}" $variant {
    {{canary_pct}}%  canary;
    *                stable;
}

upstream stable { server {{stable_upstream}}; }
upstream canary { server {{canary_upstream}}; }

server {
    listen 80;
    location / {
        proxy_pass http://$variant;
    }
}
